s=(r/'app/source/native_login.c').read_text()
def extract(a,b):return s[s.index(a):s.index(b)]
header='#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <ctype.h>\n#include <assert.h>\ntypedef unsigned u32;typedef int Result;\ntypedef struct {int conn;} TlsSession;\n#define R_FAILED(rc) ((rc)!=0)\nstatic unsigned last_http_status,last_discord_error;static int last_captcha_required;\nstatic const char *fixture;static size_t fixture_at,fixture_size;static char request[8192];static size_t request_at;\nstatic int tls_open(TlsSession *s,const char *host){(void)s;(void)host;fixture_at=0;request_at=0;return 1;}\nstatic int tls_send(TlsSession *s,const void *data,size_t n){(void)s;assert(request_at+n<sizeof(request));memcpy(request+request_at,data,n);request_at+=n;request[request_at]=0;return 1;}\nstatic void wipe(void *p,size_t n){memset(p,0,n);}\nstatic int sslConnectionRead(int *s,void *out,u32 cap,u32 *got){(void)s;size_t n=(fixture_size?fixture_size:strlen(fixture))-fixture_at;if(n>17)n=17;if(n>cap)n=cap;memcpy(out,fixture+fixture_at,n);fixture_at+=n;*got=(u32)n;return 0;}\n'
tail='\nint main(void){\n TlsSession s={0};char out[4096];\n fixture="HTTP/1.1 200 OK\\r\\nContent-Length: 24\\r\\n\\r\\n{\\"encrypted_token\\":\\"x\\"} ";\n assert(http_request(&s,"discord.com","POST","/api/v10/users/@me/remote-auth/login","{\\"ticket\\":\\"test-only\\"}",NULL,out,sizeof(out)));\n assert(strstr(request,"Origin: https://discord.com\\r\\n"));assert(strstr(request,"Content-Length: 22\\r\\n"));assert(strstr(out,"encrypted_token"));\n fixture="HTTP/1.1 400 Bad Request\\r\\nContent-Length: 26\\r\\n\\r\\n{\\"captcha_key\\":[\\"secret\\"]}";\n assert(!http_request(&s,"discord.com","POST","/",NULL,NULL,out,sizeof(out)));assert(last_http_status==400 && last_captcha_required);\n fixture="HTTP/1.1 400 Bad Request\\r\\nTransfer-Encoding: chunked\\r\\n\\r\\ne\\r\\n{\\"code\\":50035}\\r\\n0\\r\\n\\r\\n";\n assert(!http_request(&s,"discord.com","POST","/",NULL,NULL,out,sizeof(out)));assert(last_http_status==400 && last_discord_error==50035 && !last_captcha_required);\n fixture="HTTP/1.1 200 OK\\r\\nContent-Length: 200\\r\\n\\r\\n{}";\n assert(!http_request(&s,"discord.com","GET","/",NULL,NULL,out,sizeof(out)));\n fixture="HTTP/1.1 429 Too Many Requests\\r\\nContent-Length: 2\\r\\n\\r\\n{}";\n assert(!http_request(&s,"discord.com","GET","/",NULL,NULL,out,sizeof(out)));assert(last_http_status==429 && !last_captcha_required && last_discord_error==0);\n puts("PASS native HTTP: ticket request, 200 token, 400 captcha, chunked error code, truncation, rate limit, state reset");\n}\n'
